    public static int PaAction(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells idx, emon.Port.Cells pg, emon.Port.Cells txt, int act, emon.Port.Cells @out, int row) {
        // Read an action dictionary into annotation/outline-style cells at out[row]: the
        // first action's kind at row+0, its target run at row+1, its destination at row+3.
        // (Both `an` and `ol` lay these out the same, relative to `row`.) Answers how many
        // actions the /Next chain holds (at most 8), counting this one.
        int kind = 0;
        int v = 0;
        int cnt = 0;
        int cur = act;
        int nx = 0;
        int guard = 0;
        if (act == 0) {
            return 0;
        }
        if (Pdflex.PlKindOf(ar, act) != 7) {
            return 0;
        }
        v = Pdfx.PxDget(src, ar, dc, a, b, st, act, Pdfxnames.PxS());
        kind = PaActKind(ar, v);
        emon.Port.CellsSet(@out, row, kind);
        if (kind == 1) {
            v = Pdfx.PxDget(src, ar, dc, a, b, st, act, Pdfxnames.PxUri());
            PaUriTo(txt, ar, v, @out, row + 1);
        }
        if (kind == 2) {
            v = Pdfx.PxGet(ar, act, Pdfxnames.PxD());
            Pdfx.PxDestOf(src, ar, dc, a, b, st, idx, pg, txt, v, @out, row + 3);
        }
        if (kind == 3) {
            v = Pdfx.PxGet(ar, act, Pdfxnames.PxD());
            Pdfx.PxRemoteSet(idx, 1);
            Pdfx.PxDestOf(src, ar, dc, a, b, st, idx, pg, txt, v, @out, row + 3);
            Pdfx.PxRemoteSet(idx, 0);
            v = Pdfdoc.PdDget(src, ar, dc, a, b, st, act, Pdfnames.PnF());
            PaFilespecTo(src, ar, dc, a, b, st, txt, v, @out, row + 1);
        }
        if (kind == 5) {
            v = Pdfdoc.PdDget(src, ar, dc, a, b, st, act, Pdfnames.PnF());
            PaFilespecTo(src, ar, dc, a, b, st, txt, v, @out, row + 1);
        }
        if (kind == 6) {
            v = Pdfdoc.PdDget(src, ar, dc, a, b, st, act, Pdfnames.PnN());
            PaTextTo(txt, ar, v, @out, row + 1);
        }
        // The chain: /Next is an action or an array of them; count, do not follow deeper.
        cnt = 1;
        cur = act;
        while (guard < 8) {
            guard += 1;
            nx = Pdfx.PxDget(src, ar, dc, a, b, st, cur, Pdfxnames.PxNext());
            if (nx == 0) {
                guard = 99;
