                cnt += Pdflex.PlCount(ar, nx);
                guard = 99;
            } else if (Pdflex.PlKindOf(ar, nx) == 7) {
                cnt += 1;
                cur = nx;
            } else {
                guard = 99;
            }
        }
        if (cnt > 8) {
            cnt = 8;
        }
        return cnt;
    }
