        int c = 0;
        int c2 = 0;
        int inbt = 0;
        int pend = 0;
        int any = 0;
        int lastzero = 0;
        int depth = 0;
        int emit = 0;
        int o = 0;
        int k = 0;
        int hi = 0;
        int nib = 0;
        int ws = 0;
        int we = 0;
        int wl = 0;
        int last = 0;
        int digit = 0;
        int nonzero = 0;
        if (n > 65536) {
            n = 65536;
        }
        while (i < n) {
            c = emon.Port.CellsAt(w, i);
            emit = -1;
            if (c == 37) {
                while ((i < n) && (emon.Port.CellsAt(w, i) != 10) && (emon.Port.CellsAt(w, i) != 13)) {
                    i += 1;
                }
            } else if (c == 40) {
                depth = 1;
                i += 1;
                while ((i < n) && (depth > 0)) {
                    c = emon.Port.CellsAt(w, i);
                    i += 1;
                    emit = -1;
                    if (c == 92) {
                        if (i < n) {
                            c2 = emon.Port.CellsAt(w, i);
                            i += 1;
                            if (c2 == 110) {
                                emit = 10;
                            }
                            if (c2 == 114) {
                                emit = 13;
                            }
                            if (c2 == 116) {
                                emit = 9;
                            }
                            if (c2 == 98) {
                                emit = 8;
                            }
                            if (c2 == 102) {
                                emit = 12;
                            }
                            if ((c2 == 40) || (c2 == 41) || (c2 == 92)) {
                                emit = c2;
                            }
                            if ((c2 >= 48) && (c2 <= 55)) {
                                o = c2 - 48;
                                k = 0;
                                while ((k < 2) && (i < n) && (emon.Port.CellsAt(w, i) >= 48) && (emon.Port.CellsAt(w, i) <= 55)) {
                                    o = (o * 8) + (emon.Port.CellsAt(w, i) - 48);
                                    i += 1;
                                    k += 1;
                                }
                                emit = o & 255;
                            }
                            if (c2 == 13) {
                                if ((i < n) && (emon.Port.CellsAt(w, i) == 10)) {
                                    i += 1;
                                }
                            }
                            if ((emit == -1) && (c2 != 10) && (c2 != 13) && ((c2 < 48) || (c2 > 55))) {
                                emit = c2;
                            }
                        }
                    } else {
                        if (c == 40) {
                            depth += 1;
                            emit = 40;
                        }
                        if (c == 41) {
                            depth -= 1;
                            if (depth > 0) {
                                emit = 41;
                            }
                        }
                        if ((c != 40) && (c != 41)) {
                            emit = c;
                        }
                    }
                    if ((emit >= 0) && (inbt == 1)) {
                        if ((pend == 1) && (any == 1)) {
                            Pdfx.PxPushCp(txt, 10);
                        }
                        pend = 0;
                        Pdfx.PxPushCp(txt, emit);
                        any = 1;
                    }
                }
            } else if (c == 60) {
                if (((i + 1) < n) && (emon.Port.CellsAt(w, i + 1) == 60)) {
                    i += 2;
                } else {
                    i += 1;
                    hi = -1;
                    while ((i < n) && (emon.Port.CellsAt(w, i) != 62)) {
                        nib = PaHexval(emon.Port.CellsAt(w, i));
                        if (nib >= 0) {
                            if (hi < 0) {
                                hi = nib;
                            } else {
                                emit = (hi * 16) + nib;
                                hi = -1;
                                if (inbt == 1) {
                                    if ((pend == 1) && (any == 1)) {
                                        Pdfx.PxPushCp(txt, 10);
                                    }
                                    pend = 0;
                                    Pdfx.PxPushCp(txt, emit);
                                    any = 1;
                                }
                            }
                        }
                        i += 1;
                    }
                    if (hi >= 0) {
                        if (inbt == 1) {
                            if ((pend == 1) && (any == 1)) {
                                Pdfx.PxPushCp(txt, 10);
                            }
                            pend = 0;
                            Pdfx.PxPushCp(txt, hi * 16);
                            any = 1;
                        }
                    }
                    i += 1;
                }
            } else if (c == 47) {
                i += 1;
                while ((i < n) && (PaIsDelim(emon.Port.CellsAt(w, i)) == 0)) {
                    i += 1;
                }
            } else if (PaIsDelim(c) == 1) {
                i += 1;
            } else {
                ws = i;
                while ((i < n) && (PaIsDelim(emon.Port.CellsAt(w, i)) == 0)) {
                    i += 1;
                }
                we = i;
                wl = we - ws;
                c2 = emon.Port.CellsAt(w, ws);
                digit = 0;
                if (((c2 >= 48) && (c2 <= 57)) || (c2 == 45) || (c2 == 43) || (c2 == 46)) {
                    digit = 1;
                    nonzero = 0;
                    k = ws;
                    while (k < we) {
                        last = emon.Port.CellsAt(w, k);
                        if ((last >= 49) && (last <= 57)) {
                            nonzero = 1;
                        }
                        k += 1;
                    }
                    if (nonzero == 1) {
                        lastzero = 0;
                    } else {
                        lastzero = 1;
                    }
                }
                if (digit == 0) {
                    if ((wl == 2) && (c2 == 66) && (emon.Port.CellsAt(w, ws + 1) == 84)) {
                        inbt = 1;
                    }
                    if ((wl == 2) && (c2 == 69) && (emon.Port.CellsAt(w, ws + 1) == 84)) {
                        inbt = 0;
                        pend = 1;
                    }
                    if ((wl == 2) && (c2 == 84) && ((emon.Port.CellsAt(w, ws + 1) == 100) || (emon.Port.CellsAt(w, ws + 1) == 68))) {
                        if (lastzero == 0) {
                            pend = 1;
                        }
                    }
                    if ((wl == 2) && (c2 == 84) && (emon.Port.CellsAt(w, ws + 1) == 42)) {
                        pend = 1;
                    }
                    if ((wl == 1) && ((c2 == 39) || (c2 == 34))) {
                        pend = 1;
                    }
                }
            }
        }
        // Trailing white space and line breaks.
        while (emon.Port.CellsLen(txt) > n0) {
            c = emon.Port.CellsAt(txt, emon.Port.CellsLen(txt) - 1);
            if ((c == 10) || (c == 32) || (c == 13) || (c == 9)) {
                emon.Port.CellsDrop(txt, emon.Port.CellsLen(txt) - 1);
            } else {
                return emon.Port.CellsLen(txt) - n0;
            }
        }
        return 0;
    }
    internal static int PaApRaw(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, int adict) {
        // The annotation's normal appearance, RAW: /AP /N, or, when that is a dictionary of
        // states, the entry /AS names. 0 when there is none.
        int ap = Pdfx.PxDget(src, ar, dc, a, b, st, adict, Pdfxnames.PxAp());
        int n = 0;
        int @as = 0;
        int nr = 0;
        if (ap == 0) {
            return 0;
        }
        if (Pdflex.PlKindOf(ar, ap) != 7) {
            return 0;
        }
        nr = Pdflex.PlDictGet(ar, ap, Pdfnames.PnN());
        if (nr == 0) {
            return 0;
        }
        n = Pdfdoc.PdResolve(src, ar, dc, a, b, st, nr);
        if (n == 0) {
            return 0;
        }
        if (Pdflex.PlKindOf(ar, n) == 8) {
            return nr;
        }
        if (Pdflex.PlKindOf(ar, n) == 7) {
            @as = Pdfx.PxDget(src, ar, dc, a, b, st, adict, Pdfxnames.PxAs());
            if (@as == 0) {
                return 0;
            }
            return Pdfx.PxDictFindPlain(ar, n, @as);
        }
        return 0;
    }
    internal static int PaApText(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells w, emon.Port.Cells txt, int raw) {
        // The text of the appearance stream `raw` (from `pa-ap-raw`): decoded into `w`,
        // scanned into `txt`. Answers the number of code points, 0 when none (or none
        // readable). `w` must not be `a`, `b` or `st`.
        int sh = Pdfdoc.PdResolve(src, ar, dc, a, b, st, raw);
        if (sh == 0) {
            return 0;
        }
        if (Pdflex.PlKindOf(ar, sh) != 8) {
            return 0;
        }
        Pdfdoc.PdStreamData(src, ar, dc, a, b, st, sh, w);
        return PaScanText(w, txt);
    }
    internal static int PaSigNew(emon.Port.Cells sg, int field) {
        // Push a signature row that says nothing; answers its row.
        int row = emon.Port.CellsLen(sg) / SgStride;
        int at = emon.Port.CellsLen(sg);
        int k = 0;
        while (k < SgStride) {
            emon.Port.CellsPush(sg, 0);
            k += 1;
        }
        emon.Port.CellsSet(sg, at, field);
        emon.Port.CellsSet(sg, at + 1, -1);
        emon.Port.CellsSet(sg, at + 2, -1);
        emon.Port.CellsSet(sg, at + 7, -1);
        emon.Port.CellsSet(sg, at + 9, -1);
        k = 11;
        while (k < 18) {
            emon.Port.CellsSet(sg, at + k, -1);
            k += 1;
        }
        emon.Port.CellsSet(sg, at + 18, -1);
        emon.Port.CellsSet(sg, at + 20, -1);
        emon.Port.CellsSet(sg, at + 22, -1);
        emon.Port.CellsSet(sg, at + 24, -1);
        emon.Port.CellsSet(sg, at + 26, -1);
        k = 28;
        while (k < 32) {
            emon.Port.CellsSet(sg, at + k, -1);
            k += 1;
        }
        emon.Port.CellsSet(sg, at + 36, -1);
        return row;
    }
    internal static int PaAsnCp(emon.Port.Cells ar, int h, int i, int end, int tag, emon.Port.Cells @out) {
        // Append to `out` the characters of the ASN.1 string whose content is the bytes [i, end) of string `h`; `tag` is its universal tag: 12 UTF8String is decoded as
        // UTF-8 (a malformed byte is U+FFFD), 30 BMPString as UTF-16BE, every other as Latin-1. Answers the code points appended.
        int k = i;
        int c = 0;
        int n = 0;
        int cp = 0;
        int need = 0;
        while (k < end) {
            c = Pdfx.PxBat(ar, h, k);
            cp = c;
            if (tag == 30) {
                if ((k + 1) < end) {
                    cp = (c * 256) + Pdfx.PxBat(ar, h, k + 1);
                }
                k += 1;
            }
            if ((tag == 12) && (c >= 128)) {
                need = 0;
                if ((c >= 194) && (c < 224)) {
                    need = 1;
                    cp = c - 192;
                }
                if ((c >= 224) && (c < 240)) {
                    need = 2;
                    cp = c - 224;
                }
                if ((c >= 240) && (c < 245)) {
                    need = 3;
                    cp = c - 240;
                }
                if (need == 0) {
                    cp = 65533;
                } else if ((k + need) > (end - 1)) {
                    cp = 65533;
                    need = 0;
                } else {
                    while (need > 0) {
                        k += 1;
                        cp = (cp * 64) + (Pdfx.PxBat(ar, h, k) & 63);
                        need -= 1;
                    }
                }
            }
            Pdfx.PxPushCp(@out, cp);
            n += 1;
            k += 1;
        }
        return n;
    }
    internal static int PaCertName(emon.Port.Cells ar, int h, emon.Port.Cells txt, emon.Port.Cells sg, int at) {
        // The common name of the SIGNER's certificate, read as bytes from the PKCS#7 in the /Contents string `h`; a run at sg[at, at+2), absent (-1 0) when there is none.
        // NOTHING IS VERIFIED: the bytes are searched for the AttributeType commonName (55 04 03) followed by a UTF8String, PrintableString, T61String, IA5String or BMPString of
        // a short length, and the SECOND one is taken (a certificate lists its issuer before its subject, and the signer's is the first certificate of the set: Adobe and openssl write
        // it so), else the first. A name of a self-signed certificate is the same twice. D900.
        int n = Pdfx.PxBlen(ar, h);
        int i = 0;
        int seen = 0;
        int tag = 0;
        int clen = 0;
        int s0 = -1;
        int l0 = 0;
        int t0 = 0;
        int s1 = -1;
        int l1 = 0;
        int t1 = 0;
        emon.Port.CellsSet(sg, at, -1);
        emon.Port.CellsSet(sg, at + 1, 0);
        while (((i + 5) < n) && (seen < 2)) {
            if ((Pdfx.PxBat(ar, h, i) == 85) && ((Pdfx.PxBat(ar, h, i + 1) == 4) && (Pdfx.PxBat(ar, h, i + 2) == 3))) {
                tag = Pdfx.PxBat(ar, h, i + 3);
                clen = Pdfx.PxBat(ar, h, i + 4);
                if (((tag == 12) || ((tag == 19) || ((tag == 20) || ((tag == 22) || (tag == 30))))) && ((clen > 0) && ((clen < 128) && (((i + 5) + clen) <= n)))) {
                    if (seen == 0) {
                        s0 = i + 5;
                        l0 = clen;
                        t0 = tag;
                    }
                    if (seen == 1) {
                        s1 = i + 5;
                        l1 = clen;
                        t1 = tag;
                    }
                    seen += 1;
                    i = (i + 4) + clen;
                }
            }
            i += 1;
        }
        if (s0 == -1) {
            return 0;
        }
        int start = emon.Port.CellsLen(txt);
        int cnt = 0;
        if (seen == 2) {
            cnt = PaAsnCp(ar, h, s1, s1 + l1, t1, txt);
        } else {
            cnt = PaAsnCp(ar, h, s0, s0 + l0, t0, txt);
        }
        emon.Port.CellsSet(sg, at, start);
        emon.Port.CellsSet(sg, at + 1, cnt);
        return cnt;
    }
    internal static int PaSigFill(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells txt, emon.Port.Cells sg, int row, int sd, int bits) {
        // Fill signature row `row` from the signature dictionary `sd` (resolved). Nothing
        // is validated: these are the strings the dictionary holds.
        int at = row * SgStride;
        int v = 0;
        int br = 0;
        int e = 0;
        int j = 0;
        int fl = bits;
        int n = 0;
        v = Pdfx.PxDget(src, ar, dc, a, b, st, sd, Pdfxnames.PxName());
        PaTextTo(txt, ar, v, sg, at + 7);
        v = Pdfx.PxDget(src, ar, dc, a, b, st, sd, Pdfxnames.PxM());
        PaTextTo(txt, ar, v, sg, at + 9);
        Pdfx.PxDateParse(txt, emon.Port.CellsAt(sg, at + 9), emon.Port.CellsAt(sg, at + 10), sg, at + 11);
        v = Pdfx.PxDget(src, ar, dc, a, b, st, sd, Pdfxnames.PxReason());
        PaTextTo(txt, ar, v, sg, at + 18);
        v = Pdfx.PxDget(src, ar, dc, a, b, st, sd, Pdfxnames.PxLocation());
        PaTextTo(txt, ar, v, sg, at + 20);
        v = Pdfx.PxDget(src, ar, dc, a, b, st, sd, Pdfxnames.PxContactInfo());
        PaTextTo(txt, ar, v, sg, at + 22);
        v = Pdfdoc.PdDget(src, ar, dc, a, b, st, sd, Pdfnames.PnFilter());
        PaTextTo(txt, ar, v, sg, at + 24);
        v = Pdfx.PxDget(src, ar, dc, a, b, st, sd, Pdfxnames.PxSubFilter());
        PaTextTo(txt, ar, v, sg, at + 26);
        br = Pdfx.PxDget(src, ar, dc, a, b, st, sd, Pdfxnames.PxByteRange());
        if ((br != 0) && (Pdflex.PlKindOf(ar, br) == 6)) {
            n = Pdflex.PlCount(ar, br);
            emon.Port.CellsSet(sg, at + 34, n / 2);
            if (n >= 4) {
                fl |= 2;
            }
            e = Pdflex.PlFirst(ar, br);
            j = 0;
            while ((e != 0) && (j < 4)) {
                v = Pdfdoc.PdResolve(src, ar, dc, a, b, st, e);
                emon.Port.CellsSet(sg, (at + 28) + j, Pdfx.PxIntOf(ar, v, -1));
                e = Pdflex.PlNext(ar, e);
                j += 1;
            }
        }
        v = Pdfdoc.PdDget(src, ar, dc, a, b, st, sd, Pdfnames.PnContents());
        if ((v != 0) && (Pdflex.PlKindOf(ar, v) == 5)) {
            emon.Port.CellsSet(sg, at + 32, Pdflex.PlStrLen(ar, v));
            PaCertName(ar, v, txt, sg, at + 36);
            fl |= 1;
        }
        v = Pdfdoc.PdDget(src, ar, dc, a, b, st, sd, Pdfnames.PnType());
        if (Pdfx.PxIs(ar, v, Pdfxnames.PxDocTimeStamp()) == 1) {
            fl |= 4;
        }
        emon.Port.CellsSet(sg, at + 33, fl);
        return 0;
    }
    internal static int PaFtCode(emon.Port.Cells ar, int h) {
        // A /FT name as an `fd-ft`.
        if (h == 0) {
            return 0;
        }
        if (Pdfx.PxIs(ar, h, Pdfxnames.PxBtn()) == 1) {
            return 1;
        }
        if (Pdfx.PxIs(ar, h, Pdfxnames.PxTx()) == 1) {
            return 2;
        }
        if (Pdfx.PxIs(ar, h, Pdfxnames.PxCh()) == 1) {
            return 3;
        }
        if (Pdfx.PxIs(ar, h, Pdfxnames.PxSig()) == 1) {
            return 4;
        }
        return 0;
    }
    internal static int PaFlagSet(int ff, int bit) {
        // 1 when the field flag whose value is `bit` (a power of two) is set.
        return (ff / bit) % 2;
    }
    internal static int PaFdKind(int ft, int ff) {
        if (ft == 1) {
            if (PaFlagSet(ff, 65536) == 1) {
                return 1;
            }
            if (PaFlagSet(ff, 32768) == 1) {
                return 3;
            }
            return 2;
        }
        if (ft == 2) {
            return 4;
        }
        if (ft == 3) {
            if (PaFlagSet(ff, 131072) == 1) {
                return 5;
            }
            return 6;
        }
        if (ft == 4) {
            return 7;
        }
        return 0;
    }
    internal static int PaFdNew(emon.Port.Cells fd) {
        // Push a terminal field row that says nothing; answers its row.
        int row = emon.Port.CellsLen(fd) / FdStride;
        int at = emon.Port.CellsLen(fd);
        int k = 0;
        while (k < FdStride) {
            emon.Port.CellsPush(fd, 0);
            k += 1;
        }
        emon.Port.CellsSet(fd, at + 2, -1);
        emon.Port.CellsSet(fd, at + 8, -1);
        emon.Port.CellsSet(fd, at + 11, -1);
        emon.Port.CellsSet(fd, at + 13, -1);
        emon.Port.CellsSet(fd, at + 15, -1);
        emon.Port.CellsSet(fd, at + 21, -1);
        emon.Port.CellsSet(fd, at + 24, -1);
        emon.Port.CellsSet(fd, at + 25, -1);
        emon.Port.CellsSet(fd, at + 26, -1);
        emon.Port.CellsSet(fd, at + 30, -1);
        return row;
    }
    internal static int PaFdValue(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells txt, emon.Port.Cells fd, int row, int vh) {
        // Keep /V (resolved, 0 none): its kind, its text (an array's items joined with a
        // line feed) and how many values it holds.
        int at = row * FdStride;
        int kind = 0;
        int e = 0;
        int r = 0;
        int s = 0;
        int n = 0;
        int first = 1;
        if (vh == 0) {
            return 0;
        }
        kind = Pdflex.PlKindOf(ar, vh);
        if (kind == 5) {
            emon.Port.CellsSet(fd, at + 7, 1);
            emon.Port.CellsSet(fd, at + 10, 1);
            PaTextTo(txt, ar, vh, fd, at + 8);
        }
        if (kind == 4) {
            emon.Port.CellsSet(fd, at + 7, 2);
            emon.Port.CellsSet(fd, at + 10, 1);
            PaTextTo(txt, ar, vh, fd, at + 8);
        }
        if (kind == 6) {
            emon.Port.CellsSet(fd, at + 7, 3);
            s = emon.Port.CellsLen(txt);
            e = Pdflex.PlFirst(ar, vh);
            while (e != 0) {
                r = Pdfdoc.PdResolve(src, ar, dc, a, b, st, e);
                if ((r != 0) && ((Pdflex.PlKindOf(ar, r) == 5) || (Pdflex.PlKindOf(ar, r) == 4))) {
                    if (first == 0) {
                        Pdfx.PxPushCp(txt, 10);
                    }
                    first = 0;
                    Pdfx.PxTextPush(ar, r, txt);
                    n += 1;
                }
                e = Pdflex.PlNext(ar, e);
            }
            emon.Port.CellsSet(fd, at + 8, s);
            emon.Port.CellsSet(fd, at + 9, emon.Port.CellsLen(txt) - s);
            emon.Port.CellsSet(fd, at + 10, n);
        }
        if (kind == 8) {
            emon.Port.CellsSet(fd, at + 7, 4);
        }
        if (kind == 7) {
            emon.Port.CellsSet(fd, at + 7, 5);
        }
        if ((kind != 5) && (kind != 4) && (kind != 6) && (kind != 8) && (kind != 7)) {
            emon.Port.CellsSet(fd, at + 7, 6);
        }
        emon.Port.CellsSet(fd, at + 31, vh);
        return 0;
    }
    internal static int PaFieldRow(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells txt, emon.Port.Cells fs, emon.Port.Cells fd, emon.Port.Cells sg, int node, int num, int depth) {
        // A terminal field: one row from the node and the frame its ancestors left.
        int fo = (depth + 1) * FsStride;
        int row = PaFdNew(fd);
        int at = row * FdStride;
        int ft = emon.Port.CellsAt(fs, fo);
        int ff = emon.Port.CellsAt(fs, fo + 1);
        int vh = emon.Port.CellsAt(fs, fo + 2);
        int dvh = emon.Port.CellsAt(fs, fo + 3);
        int v = 0;
        int srow = 0;
        emon.Port.CellsSet(fd, at, num);
        emon.Port.CellsSet(fd, at + 1, depth + 1);
        emon.Port.CellsSet(fd, at + 2, emon.Port.CellsAt(fs, fo + 6));
        emon.Port.CellsSet(fd, at + 3, emon.Port.CellsAt(fs, fo + 7));
        emon.Port.CellsSet(fd, at + 4, ft);
        emon.Port.CellsSet(fd, at + 5, ff);
        emon.Port.CellsSet(fd, at + 6, PaFdKind(ft, ff));
        emon.Port.CellsSet(fd, at + 25, emon.Port.CellsAt(fs, fo + 5));
        emon.Port.CellsSet(fd, at + 26, emon.Port.CellsAt(fs, fo + 4));
        PaFdValue(src, ar, dc, a, b, st, txt, fd, row, vh);
        if (dvh != 0) {
            if ((Pdflex.PlKindOf(ar, dvh) == 5) || (Pdflex.PlKindOf(ar, dvh) == 4)) {
                PaTextTo(txt, ar, dvh, fd, at + 11);
            }
        }
        v = Pdfx.PxDget(src, ar, dc, a, b, st, node, Pdfxnames.PxTu());
        PaTextTo(txt, ar, v, fd, at + 13);
        v = Pdfx.PxDget(src, ar, dc, a, b, st, node, Pdfxnames.PxOpt());
        if ((v != 0) && (Pdflex.PlKindOf(ar, v) == 6)) {
            emon.Port.CellsSet(fd, at + 28, Pdflex.PlCount(ar, v));
        }
        if (ft == 4) {
            if ((vh != 0) && (Pdflex.PlKindOf(ar, vh) == 7)) {
                srow = PaSigNew(sg, row);
                PaSigFill(src, ar, dc, a, b, st, txt, sg, srow, vh, 0);
                emon.Port.CellsSet(fd, at + 24, srow);
            }
        }
        return row;
    }
    internal static int PaFieldWalk(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells txt, emon.Port.Cells fs, emon.Port.Cells seen, emon.Port.Cells fm, emon.Port.Cells fd, emon.Port.Cells sg, int h0, int depth) {
        // One node of the AcroForm field tree. Inherited: /FT /Ff /V /DV /Q /MaxLen (from
        // the frame of the parent, `FS_STRIDE` cells a level: ft ff v dv q maxlen name-run).
        // A node with a child that has a /T (or /Kids of its own) is not terminal and only
        // those children are fields; one without is a field whose children are widgets.
        if (depth > FsDepth) {
            return 0;
        }
        if ((emon.Port.CellsLen(fd) / FdStride) >= PaFields) {
            return 0;
        }
        int node = Pdfdoc.PdResolve(src, ar, dc, a, b, st, h0);
        int fo = (depth + 1) * FsStride;
        int po = depth * FsStride;
        int num = 0;
        int k = 0;
        int v = 0;
        int t = 0;
        int s = 0;
        int ps = 0;
        int pl = 0;
        int x = 0;
        int kids = 0;
        int e = 0;
        int kr = 0;
        int fr = 0;
        int subs = 0;
        if (node == 0) {
            return 0;
        }
        if (Pdflex.PlKindOf(ar, node) != 7) {
            return 0;
        }
        if (Pdflex.PlKindOf(ar, h0) == 9) {
            num = Pdflex.PlIntValue(ar, h0);
        }
        if (Pdfx.PxSeenMark(seen, num) == 1) {
            return 0;
        }
        while (k < FsStride) {
            x = emon.Port.CellsAt(fs, po + k);
            emon.Port.CellsSet(fs, fo + k, x);
            k += 1;
        }
        v = Pdfx.PxDget(src, ar, dc, a, b, st, node, Pdfxnames.PxFt());
        if (PaFtCode(ar, v) != 0) {
            emon.Port.CellsSet(fs, fo, PaFtCode(ar, v));
        }
        v = Pdfx.PxDget(src, ar, dc, a, b, st, node, Pdfxnames.PxFf());
        if (Pdfx.PxIsNum(ar, v) == 1) {
            emon.Port.CellsSet(fs, fo + 1, Pdfx.PxIntOf(ar, v, 0));
        }
        if (Pdfx.PxHas(src, ar, dc, a, b, st, node, Pdfxnames.PxV()) == 1) {
            v = Pdfx.PxDget(src, ar, dc, a, b, st, node, Pdfxnames.PxV());
            emon.Port.CellsSet(fs, fo + 2, v);
        }
        if (Pdfx.PxHas(src, ar, dc, a, b, st, node, Pdfxnames.PxDv()) == 1) {
            v = Pdfx.PxDget(src, ar, dc, a, b, st, node, Pdfxnames.PxDv());
            emon.Port.CellsSet(fs, fo + 3, v);
        }
        v = Pdfx.PxDget(src, ar, dc, a, b, st, node, Pdfxnames.PxQ());
        if (Pdfx.PxIsNum(ar, v) == 1) {
            emon.Port.CellsSet(fs, fo + 4, Pdfx.PxIntOf(ar, v, -1));
        }
        v = Pdfx.PxDget(src, ar, dc, a, b, st, node, Pdfxnames.PxMaxLen());
        if (Pdfx.PxIsNum(ar, v) == 1) {
            emon.Port.CellsSet(fs, fo + 5, Pdfx.PxIntOf(ar, v, -1));
        }
        // The name: the parent's, a dot, and this node's /T.
        t = Pdfx.PxDget(src, ar, dc, a, b, st, node, Pdfxnames.PxT());
        ps = emon.Port.CellsAt(fs, po + 6);
        pl = emon.Port.CellsAt(fs, po + 7);
        s = emon.Port.CellsLen(txt);
        if ((t != 0) && (Pdflex.PlKindOf(ar, t) == 5)) {
            k = 0;
            while (k < pl) {
                x = emon.Port.CellsAt(txt, ps + k);
                emon.Port.CellsPush(txt, x);
                k += 1;
            }
            if (pl > 0) {
                emon.Port.CellsPush(txt, 46);
            }
            Pdfx.PxTextPush(ar, t, txt);
            emon.Port.CellsSet(fs, fo + 6, s);
            emon.Port.CellsSet(fs, fo + 7, emon.Port.CellsLen(txt) - s);
        } else {
            k = 0;
            while (k < pl) {
                x = emon.Port.CellsAt(txt, ps + k);
                emon.Port.CellsPush(txt, x);
                k += 1;
            }
            emon.Port.CellsSet(fs, fo + 6, s);
            emon.Port.CellsSet(fs, fo + 7, pl);
            if (pl == 0) {
                emon.Port.CellsSet(fs, fo + 6, -1);
            }
        }
        kids = Pdfdoc.PdDget(src, ar, dc, a, b, st, node, Pdfnames.PnKids());
        if ((kids != 0) && (Pdflex.PlKindOf(ar, kids) == 6)) {
            e = Pdflex.PlFirst(ar, kids);
            while (e != 0) {
                kr = Pdfdoc.PdResolve(src, ar, dc, a, b, st, e);
                if ((kr != 0) && (Pdflex.PlKindOf(ar, kr) == 7)) {
                    if ((Pdfx.PxGet(ar, kr, Pdfxnames.PxT()) != 0) || (Pdflex.PlDictGet(ar, kr, Pdfnames.PnKids()) != 0)) {
                        subs += 1;
                    }
                }
                e = Pdflex.PlNext(ar, e);
            }
        }
        if (subs > 0) {
            e = Pdflex.PlFirst(ar, kids);
            while (e != 0) {
                kr = Pdfdoc.PdResolve(src, ar, dc, a, b, st, e);
                if ((kr != 0) && (Pdflex.PlKindOf(ar, kr) == 7)) {
                    if ((Pdfx.PxGet(ar, kr, Pdfxnames.PxT()) != 0) || (Pdflex.PlDictGet(ar, kr, Pdfnames.PnKids()) != 0)) {
                        PaFieldWalk(src, ar, dc, a, b, st, txt, fs, seen, fm, fd, sg, e, depth + 1);
                    }
                }
                e = Pdflex.PlNext(ar, e);
            }
        } else {
            fr = PaFieldRow(src, ar, dc, a, b, st, txt, fs, fd, sg, node, num, depth);
            if ((num > 0) && (num < emon.Port.CellsLen(fm))) {
                emon.Port.CellsSet(fm, num, fr + 1);
            }
        }
        return 0;
    }
    internal static int PaFindField(emon.Port.Cells fm, int num) {
        // The row of the terminal field whose object number is `num` (the field map holds row
        // + 1 at each object number), -1 when none.
        if (num <= 0) {
            return -1;
        }
        if (num >= emon.Port.CellsLen(fm)) {
            return -1;
        }
        return emon.Port.CellsAt(fm, num) - 1;
    }
    internal static int PaAnNew(emon.Port.Cells an, int pi) {
        // Push an annotation row that says nothing, on page `pi`; answers its row.
        int row = emon.Port.CellsLen(an) / AnStride;
        int at = emon.Port.CellsLen(an);
        int k = 0;
        while (k < AnStride) {
            emon.Port.CellsPush(an, 0);
            k += 1;
        }
        emon.Port.CellsSet(an, at, pi);
        emon.Port.CellsSet(an, at + 13, -1);
        Pdfx.PxDestInit(an, at + 15);
        emon.Port.CellsSet(an, at + 23, -1);
        emon.Port.CellsSet(an, at + 25, -1);
        emon.Port.CellsSet(an, at + 27, -1);
        emon.Port.CellsSet(an, at + 29, -1);
        emon.Port.CellsSet(an, at + 32, -1);
        emon.Port.CellsSet(an, at + 35, -1);
        emon.Port.CellsSet(an, at + 36, -1);
        return row;
    }
    internal static int PaNumAt(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, int arr, int i) {
        // The i-th element of an array as centipoints; (px-null) when it is not a number.
        int raw = Pdfx.PxNth(ar, arr, i);
        int v = Pdfdoc.PdResolve(src, ar, dc, a, b, st, raw);
        if (Pdfx.PxIsNum(ar, v) == 0) {
            return Pdfx.PxNull();
        }
        return Pdfx.PxClampCp(Pdflex.PlNumCp(ar, v));
    }
    internal static int PaRectInto(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells pg, int pi, int arr, emon.Port.Cells @out, int at) {
        // A /Rect (four numbers) into out[at, at+4) in page space and out[at+4, at+8) as
        // written and normalized (user space). Answers 1 when it was a rectangle.
        if (arr == 0) {
            return 0;
        }
        if (Pdflex.PlKindOf(ar, arr) != 6) {
            return 0;
        }
        int x0 = PaNumAt(src, ar, dc, a, b, st, arr, 0);
        int y0 = PaNumAt(src, ar, dc, a, b, st, arr, 1);
        int x1 = PaNumAt(src, ar, dc, a, b, st, arr, 2);
        int y1 = PaNumAt(src, ar, dc, a, b, st, arr, 3);
        int t = 0;
        int p0 = 0;
        int p1 = 0;
        int q0 = 0;
        int q1 = 0;
        int lo = 0;
        int hi = 0;
        if ((x0 == Pdfx.PxNull()) || (y0 == Pdfx.PxNull()) || (x1 == Pdfx.PxNull()) || (y1 == Pdfx.PxNull())) {
            return 0;
        }
        if (x0 > x1) {
            t = x0;
            x0 = x1;
            x1 = t;
        }
        if (y0 > y1) {
            t = y0;
            y0 = y1;
            y1 = t;
        }
        emon.Port.CellsSet(@out, at + 4, x0);
        emon.Port.CellsSet(@out, at + 5, y0);
        emon.Port.CellsSet(@out, at + 6, x1);
        emon.Port.CellsSet(@out, at + 7, y1);
        // The four corners mapped; the box around them.
        p0 = Pdfx.PxPageX(pg, pi, x0, y0);
        q0 = Pdfx.PxPageY(pg, pi, x0, y0);
        p1 = Pdfx.PxPageX(pg, pi, x1, y1);
        q1 = Pdfx.PxPageY(pg, pi, x1, y1);
        lo = p0;
        if (p1 < lo) {
            lo = p1;
        }
        hi = p0;
        if (p1 > hi) {
            hi = p1;
        }
        emon.Port.CellsSet(@out, at, lo);
        emon.Port.CellsSet(@out, at + 2, hi);
        lo = q0;
        if (q1 < lo) {
            lo = q1;
        }
        hi = q0;
        if (q1 > hi) {
            hi = q1;
        }
        emon.Port.CellsSet(@out, at + 1, lo);
        emon.Port.CellsSet(@out, at + 3, hi);
        return 1;
    }
    internal static int PaQuads(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells pg, int pi, int arr, emon.Port.Cells aq, emon.Port.Cells an, int at) {
        // /QuadPoints (groups of eight numbers) mapped to page space into `aq`, at most 64
        // quadrilaterals; the run is recorded at an[at+36, at+38).
        if (arr == 0) {
            return 0;
        }
        if (Pdflex.PlKindOf(ar, arr) != 6) {
            return 0;
        }
        int n = Pdflex.PlCount(ar, arr) / 8;
        int q = 0;
        int k = 0;
        int x = 0;
        int y = 0;
        if (n == 0) {
            return 0;
        }
        if (n > 64) {
            n = 64;
        }
        emon.Port.CellsSet(an, at + 36, emon.Port.CellsLen(aq) / 8);
        emon.Port.CellsSet(an, at + 37, n);
        while (q < n) {
            k = 0;
            while (k < 4) {
                x = PaNumAt(src, ar, dc, a, b, st, arr, (q * 8) + (k * 2));
                y = PaNumAt(src, ar, dc, a, b, st, arr, ((q * 8) + (k * 2)) + 1);
                if ((x == Pdfx.PxNull()) || (y == Pdfx.PxNull())) {
                    emon.Port.CellsPush(aq, 0);
                    emon.Port.CellsPush(aq, 0);
                } else {
                    emon.Port.CellsPush(aq, Pdfx.PxPageX(pg, pi, x, y));
                    emon.Port.CellsPush(aq, Pdfx.PxPageY(pg, pi, x, y));
                }
                k += 1;
            }
            q += 1;
        }
        return n;
    }
    internal static int PaCompare(emon.Port.Cells fd, emon.Port.Cells txt, int frow, int s, int n) {
        // Field row `frow` (a text or choice field) against the appearance text run (s, n):
        // set `fa`.
        int at = frow * FdStride;
        int vs = emon.Port.CellsAt(fd, at + 8);
        int vn = emon.Port.CellsAt(fd, at + 9);
        int vk = emon.Port.CellsAt(fd, at + 7);
        int r = 0;
        if (vk == 0) {
            if (n > 0) {
                r = 4;
            }
            emon.Port.CellsSet(fd, at + 23, r);
            return r;
        }
        if (n <= 0) {
            if (vn == 0) {
                r = 1;
            } else {
                r = 3;
            }
            emon.Port.CellsSet(fd, at + 23, r);
            return r;
        }
        if (Pdfx.PxRunEq(txt, vs, vn, s, n) == 1) {
            r = 1;
        } else {
            r = 2;
        }
        emon.Port.CellsSet(fd, at + 23, r);
        return r;
    }
    internal static int PaAnnot(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells idx, emon.Port.Cells pg, emon.Port.Cells txt, emon.Port.Cells w, emon.Port.Cells an, emon.Port.Cells aq, emon.Port.Cells fm, emon.Port.Cells fd, emon.Port.Cells sg, int pi, int h0) {
        // One entry of a page's /Annots: a row in `an`, and, for a widget, its field's
        // row updated. Answers the annotation row, or -1 when the entry is no dictionary.
        int dict = Pdfdoc.PdResolve(src, ar, dc, a, b, st, h0);
        int at = emon.Port.CellsLen(an);
        int row = 0;
        int num = 0;
        int sub = 0;
        int v = 0;
        int bits = 0;
        int act = 0;
        int par = 0;
        int fnum = 0;
        int frow = 0;
        int raw = 0;
        int n = 0;
        int s = 0;
        int ft = 0;
        int srow = 0;
        int x = 0;
        int fat = 0;
        int vh = 0;
        if (dict == 0) {
            return -1;
        }
        if (Pdflex.PlKindOf(ar, dict) != 7) {
            return -1;
        }
        row = PaAnNew(an, pi);
        if (Pdflex.PlKindOf(ar, h0) == 9) {
            num = Pdflex.PlIntValue(ar, h0);
        }
        emon.Port.CellsSet(an, at + 2, num);
        v = Pdfdoc.PdDget(src, ar, dc, a, b, st, dict, Pdfnames.PnSubtype());
        sub = PaSubtype(ar, v);
        emon.Port.CellsSet(an, at + 1, sub);
        emon.Port.CellsSet(an, at + 3, Pdfdoc.PdDint(src, ar, dc, a, b, st, dict, Pdfnames.PnF(), 0));
        v = Pdfx.PxDget(src, ar, dc, a, b, st, dict, Pdfxnames.PxRect());
        PaRectInto(src, ar, dc, a, b, st, pg, pi, v, an, at + 4);
        v = Pdfdoc.PdDget(src, ar, dc, a, b, st, dict, Pdfnames.PnContents());
        PaTextTo(txt, ar, v, an, at + 23);
        v = Pdfx.PxDget(src, ar, dc, a, b, st, dict, Pdfxnames.PxT());
        PaTextTo(txt, ar, v, an, at + 25);
        v = Pdfx.PxDget(src, ar, dc, a, b, st, dict, Pdfxnames.PxName());
        PaTextTo(txt, ar, v, an, at + 27);
        if (Pdfx.PxGet(ar, dict, Pdfxnames.PxAp()) != 0) {
            bits |= 1;
        }
        if (Pdfx.PxGet(ar, dict, Pdfxnames.PxOc()) != 0) {
            bits |= 2;
        }
        if (Pdflex.PlDictGet(ar, dict, Pdfnames.PnParent()) != 0) {
            bits |= 4;
        }
        v = Pdfx.PxDget(src, ar, dc, a, b, st, dict, Pdfxnames.PxCa());
        if (Pdfx.PxIsNum(ar, v) == 1) {
            emon.Port.CellsSet(an, at + 35, Pdflex.PlNumCp(ar, v) * 10);
        }
        // The action; or a /Dest on the annotation itself, which is a GoTo.
        act = Pdfx.PxDget(src, ar, dc, a, b, st, dict, Pdfxnames.PxA());
        if ((act != 0) && (Pdflex.PlKindOf(ar, act) == 7)) {
            n = PaAction(src, ar, dc, a, b, st, idx, pg, txt, act, an, at + 12);
            emon.Port.CellsSet(an, at + 31, n);
        } else if (Pdfx.PxHas(src, ar, dc, a, b, st, dict, Pdfxnames.PxDest()) == 1) {
            v = Pdfx.PxGet(ar, dict, Pdfxnames.PxDest());
            Pdfx.PxDestOf(src, ar, dc, a, b, st, idx, pg, txt, v, an, at + 15);
            emon.Port.CellsSet(an, at + 12, 2);
            emon.Port.CellsSet(an, at + 31, 1);
            bits |= 8;
        }
        v = Pdfx.PxDget(src, ar, dc, a, b, st, dict, Pdfxnames.PxQuadPoints());
        PaQuads(src, ar, dc, a, b, st, pg, pi, v, aq, an, at);
        // The appearance's text: where the annotation says something by painting it.
        raw = PaApRaw(src, ar, dc, a, b, st, dict);
        if (raw != 0) {
            if (Pdflex.PlKindOf(ar, raw) == 9) {
                emon.Port.CellsSet(an, at + 34, Pdflex.PlIntValue(ar, raw));
            }
            if ((sub == 20) || (sub == 13) || (sub == 24) || (sub == 3)) {
                s = emon.Port.CellsLen(txt);
                n = PaApText(src, ar, dc, a, b, st, w, txt, raw);
                if (n > 0) {
                    emon.Port.CellsSet(an, at + 32, s);
                    emon.Port.CellsSet(an, at + 33, n);
                }
            }
        }
        emon.Port.CellsSet(an, at + 30, bits);
        // A widget belongs to a field: its own /T makes it one, else its /Parent.
        if (sub == 20) {
            fnum = num;
            par = Pdflex.PlDictGet(ar, dict, Pdfnames.PnParent());
            if ((par != 0) && (Pdflex.PlKindOf(ar, par) == 9) && (Pdfx.PxGet(ar, dict, Pdfxnames.PxT()) == 0)) {
                fnum = Pdflex.PlIntValue(ar, par);
            }
            frow = PaFindField(fm, fnum);
            if ((frow < 0) && (fnum != num)) {
                frow = PaFindField(fm, num);
            }
            if (frow >= 0) {
                emon.Port.CellsSet(an, at + 29, frow);
                fat = frow * FdStride;
                emon.Port.CellsSet(fd, fat + 20, emon.Port.CellsAt(fd, fat + 20) + 1);
                ft = emon.Port.CellsAt(fd, fat + 4);
                // A check box or radio button: is this widget on, and is it the state /V names?
                if ((ft == 1) && ((emon.Port.CellsAt(fd, fat + 6) == 2) || (emon.Port.CellsAt(fd, fat + 6) == 3))) {
                    v = Pdfx.PxDget(src, ar, dc, a, b, st, dict, Pdfxnames.PxAs());
                    if ((v != 0) && (Pdfx.PxIs(ar, v, Pdfxnames.PxOff()) == 0)) {
                        emon.Port.CellsSet(fd, fat + 29, emon.Port.CellsAt(fd, fat + 29) + 1);
                        vh = emon.Port.CellsAt(fd, fat + 31);
                        if ((vh != 0) && (Pdflex.PlKindOf(ar, vh) == 4)) {
                            if (Pdfx.PxBytesCmp(ar, v, vh) == 0) {
                                emon.Port.CellsSet(fd, fat + 27, emon.Port.CellsAt(fd, fat + 27) + 1);
                            }
                        }
                    }
                }
                if (emon.Port.CellsAt(fd, fat + 30) == -1) {
                    emon.Port.CellsSet(fd, fat + 30, row);
                    emon.Port.CellsSet(fd, fat + 15, pi);
                    x = 0;
                    while (x < 4) {
                        emon.Port.CellsSet(fd, (fat + 16) + x, emon.Port.CellsAt(an, at + (4 + x)));
                        x += 1;
                    }
                    emon.Port.CellsSet(fd, fat + 21, emon.Port.CellsAt(an, at + 32));
                    emon.Port.CellsSet(fd, fat + 22, emon.Port.CellsAt(an, at + 33));
                    if ((ft == 2) || (ft == 3)) {
                        PaCompare(fd, txt, frow, emon.Port.CellsAt(an, at + 32), emon.Port.CellsAt(an, at + 33));
                    }
                    srow = emon.Port.CellsAt(fd, fat + 24);
                    if (srow >= 0) {
                        emon.Port.CellsSet(sg, (srow * SgStride) + 1, row);
                        emon.Port.CellsSet(sg, (srow * SgStride) + 2, pi);
                        x = 0;
                        while (x < 4) {
                            emon.Port.CellsSet(sg, ((srow * SgStride) + 3) + x, emon.Port.CellsAt(an, at + (4 + x)));
                            x += 1;
                        }
                    }
                }
            }
        }
        return row;
    }
    internal static int PaFinalize(emon.Port.Cells ar, emon.Port.Cells fd) {
        // Buttons: a field with widgets is `on` when a widget is on AND is the state /V
        // names; /V and the widgets agree when both say on or both say off.
        int n = emon.Port.CellsLen(fd) / FdStride;
        int i = 0;
        int at = 0;
        int von = 0;
        int m = 0;
        int onw = 0;
        int vh = 0;
        while (i < n) {
            at = i * FdStride;
            m = emon.Port.CellsAt(fd, at + 27);
            onw = emon.Port.CellsAt(fd, at + 29);
            emon.Port.CellsSet(fd, at + 27, -1);
            if ((emon.Port.CellsAt(fd, at + 4) == 1) && ((emon.Port.CellsAt(fd, at + 6) == 2) || (emon.Port.CellsAt(fd, at + 6) == 3))) {
                if (emon.Port.CellsAt(fd, at + 20) > 0) {
                    von = 0;
                    vh = emon.Port.CellsAt(fd, at + 31);
                    if ((vh != 0) && (Pdflex.PlKindOf(ar, vh) == 4)) {
                        if (Pdfx.PxIs(ar, vh, Pdfxnames.PxOff()) == 0) {
                            von = 1;
                        }
                    }
                    if (m > 0) {
                        emon.Port.CellsSet(fd, at + 27, 1);
                    } else {
                        emon.Port.CellsSet(fd, at + 27, 0);
                    }
                    if (((von == 1) && (m > 0)) || ((von == 0) && (onw == 0))) {
                        emon.Port.CellsSet(fd, at + 23, 1);
                    } else {
                        emon.Port.CellsSet(fd, at + 23, 2);
                    }
                }
            }
            i += 1;
        }
        return 0;
    }
    internal static int PaDigsigRow(emon.Port.Cells an, emon.Port.Cells fd, emon.Port.Cells sg, int frow) {
        // Append the synthetic `an-digsig` row (see the head of this file) of terminal field `frow` (a signature field with a widget on a page). Signed: its signature
        // dictionary has a /Contents. Nothing is verified. Answers 1 when a row was written.
        int f = frow * FdStride;
        int srow = emon.Port.CellsAt(fd, f + 24);
        int s = srow * SgStride;
        int at = emon.Port.CellsLen(an);
        int k = 0;
        if (emon.Port.CellsAt(fd, f + 15) < 0) {
            return 0;
        }
        while (k < AnStride) {
            emon.Port.CellsPush(an, 0);
            k += 1;
        }
        emon.Port.CellsSet(an, at, emon.Port.CellsAt(fd, f + 15));
        emon.Port.CellsSet(an, at + 1, AnDigsig());
        emon.Port.CellsSet(an, at + 2, emon.Port.CellsAt(fd, f));
        k = 0;
        while (k < 4) {
            emon.Port.CellsSet(an, (at + 4) + k, emon.Port.CellsAt(fd, (f + 16) + k));
            k += 1;
        }
        k = 8;
        while (k < 15) {
            emon.Port.CellsSet(an, at + k, -1);
            k += 1;
        }
        emon.Port.CellsSet(an, at + 23, -1);
        emon.Port.CellsSet(an, at + 25, emon.Port.CellsAt(fd, f + 2));
        emon.Port.CellsSet(an, at + 26, emon.Port.CellsAt(fd, f + 3));
        emon.Port.CellsSet(an, at + 27, -1);
        emon.Port.CellsSet(an, at + 29, -1);
        emon.Port.CellsSet(an, at + 32, -1);
        emon.Port.CellsSet(an, at + 34, -1);
        emon.Port.CellsSet(an, at + 35, 0);
        emon.Port.CellsSet(an, at + 36, -1);
        if (srow >= 0) {
            emon.Port.CellsSet(an, at + 23, emon.Port.CellsAt(sg, s + 7));
            emon.Port.CellsSet(an, at + 24, emon.Port.CellsAt(sg, s + 8));
            k = 0;
            while (k < 7) {
                emon.Port.CellsSet(an, (at + 8) + k, emon.Port.CellsAt(sg, (s + 11) + k));
                k += 1;
            }
            emon.Port.CellsSet(an, at + 15, emon.Port.CellsAt(sg, s + 10));
            emon.Port.CellsSet(an, at + 27, emon.Port.CellsAt(sg, s + 18));
            emon.Port.CellsSet(an, at + 28, emon.Port.CellsAt(sg, s + 19));
            emon.Port.CellsSet(an, at + 32, emon.Port.CellsAt(sg, s + 20));
            emon.Port.CellsSet(an, at + 33, emon.Port.CellsAt(sg, s + 21));
            emon.Port.CellsSet(an, at + 30, emon.Port.CellsAt(sg, s + 33));
            emon.Port.CellsSet(an, at + 34, emon.Port.CellsAt(sg, s + 36));
            emon.Port.CellsSet(an, at + 35, emon.Port.CellsAt(sg, s + 37));
        }
        return 1;
    }
    internal static int PaDigsigs(emon.Port.Cells an, emon.Port.Cells fd, emon.Port.Cells sg) {
        // The synthetic rows of every signature field (`fd` kind 7) that has a widget on a page, in field order. Answers the rows written.
        int nf = emon.Port.CellsLen(fd) / FdStride;
        int i = 0;
        int n = 0;
        while (i < nf) {
            if (emon.Port.CellsAt(fd, (i * FdStride) + 6) == 7) {
                n += PaDigsigRow(an, fd, sg, i);
            }
            i += 1;
        }
        return n;
    }
    public static int PaRun(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells pg, emon.Port.Cells idx, emon.Port.Cells txt, emon.Port.Cells w, emon.Port.Cells fs, emon.Port.Cells seen, emon.Port.Cells fm, emon.Port.Cells an, emon.Port.Cells aq, emon.Port.Cells fd, emon.Port.Cells sg) {
        // Everything P3.8 reads, after `pd-open`, `pd-pages` and `px-index-build`: fields
        // first (so a widget finds its field), then every page's /Annots, then the
        // document's /Perms /DocMDP. `an aq fd sg fs fm` are cleared; `txt` is APPENDED to (its
        // runs are offsets into it). `w` is scratch that holds a decoded appearance; `seen`
        // a visited set; `fm` maps an object number to its terminal field's row + 1. Answers
        // the number of annotations, or -1 when the source missed
        // (re-run on a fresh view; nothing here is kept).
        emon.Port.CellsDrop(an, 0);
        emon.Port.CellsDrop(aq, 0);
        emon.Port.CellsDrop(fd, 0);
        emon.Port.CellsDrop(sg, 0);
        emon.Port.CellsDrop(fs, 0);
        emon.Port.CellsDrop(fm, 0);
        int root = Pdfdoc.PdRoot(dc);
        int n = Pdfdoc.PdPgCount(pg);
        int i = 0;
        int af = 0;
        int fields = 0;
        int e = 0;
        int anArr = 0;
        int v = 0;
        int perms = 0;
        int srow = 0;
        while (i < ((FsDepth + 2) * FsStride)) {
            emon.Port.CellsPush(fs, 0);
            i += 1;
        }
        i = 0;
        while (i <= Pdfdoc.PdObjectCount(dc)) {
            emon.Port.CellsPush(fm, 0);
            i += 1;
        }
        emon.Port.CellsSet(fs, 4, -1);
        emon.Port.CellsSet(fs, 5, -1);
        emon.Port.CellsSet(fs, 6, -1);
        af = Pdfdoc.PdDget(src, ar, dc, a, b, st, root, Pdfnames.PnAcroForm());
        if ((af != 0) && (Pdflex.PlKindOf(ar, af) == 7)) {
            fields = Pdfdoc.PdDget(src, ar, dc, a, b, st, af, Pdfnames.PnFields());
            if ((fields != 0) && (Pdflex.PlKindOf(ar, fields) == 6)) {
                Pdfx.PxSeenBegin(seen, Pdfdoc.PdObjectCount(dc));
                e = Pdflex.PlFirst(ar, fields);
                while (e != 0) {
                    PaFieldWalk(src, ar, dc, a, b, st, txt, fs, seen, fm, fd, sg, e, 0);
                    if (Pdfsrc.PsMissed(src)) {
                        return -1;
                    }
                    e = Pdflex.PlNext(ar, e);
                }
            }
        }
        i = 0;
        while (i < n) {
            anArr = Pdfx.PxDget(src, ar, dc, a, b, st, Pdfdoc.PdPgNode(pg, i), Pdfxnames.PxAnnots());
            if ((anArr != 0) && (Pdflex.PlKindOf(ar, anArr) == 6)) {
                e = Pdflex.PlFirst(ar, anArr);
                while (e != 0) {
                    if ((emon.Port.CellsLen(an) / AnStride) < PaAnnots) {
                        PaAnnot(src, ar, dc, a, b, st, idx, pg, txt, w, an, aq, fm, fd, sg, i, e);
                    }
                    e = Pdflex.PlNext(ar, e);
                }
            }
            if (Pdfsrc.PsMissed(src)) {
                return -1;
            }
            i += 1;
        }
        PaFinalize(ar, fd);
        perms = Pdfx.PxDget(src, ar, dc, a, b, st, root, Pdfxnames.PxPerms());
        if ((perms != 0) && (Pdflex.PlKindOf(ar, perms) == 7)) {
            v = Pdfx.PxDget(src, ar, dc, a, b, st, perms, Pdfxnames.PxDocMdp());
            if ((v != 0) && (Pdflex.PlKindOf(ar, v) == 7)) {
                srow = PaSigNew(sg, -1);
                PaSigFill(src, ar, dc, a, b, st, txt, sg, srow, v, 8);
            }
        }
        if (Pdfsrc.PsMissed(src)) {
            return -1;
        }
        i = emon.Port.CellsLen(an) / AnStride;
        PaDigsigs(an, fd, sg);
        return i;
    }
    internal static int PaDumpAnnot(System.Text.StringBuilder t, emon.Port.Cells txt, emon.Port.Cells an, emon.Port.Cells aq, int row) {
        int at = row * AnStride;
        int k = 0;
        int q = 0;
        int v = 0;
        emon.Port.TextAscii(t, "{\"page\":");
        emon.Port.TextI32(t, emon.Port.CellsAt(an, at));
        emon.Port.TextAscii(t, ",\"subtype\":\"");
        AnSubEmitName(t, emon.Port.CellsAt(an, at + 1));
        emon.Port.TextAscii(t, "\",\"obj\":");
        emon.Port.TextI32(t, emon.Port.CellsAt(an, at + 2));
        emon.Port.TextAscii(t, ",\"flags\":");
        emon.Port.TextI32(t, emon.Port.CellsAt(an, at + 3));
        emon.Port.TextAscii(t, ",\"rect\":");
        Pdfx.PxJsonBox(t, an, at + 4);
        emon.Port.TextAscii(t, ",\"user\":");
        Pdfx.PxJsonBox(t, an, at + 8);
        if (emon.Port.CellsAt(an, at + 12) != 0) {
            emon.Port.TextAscii(t, ",\"action\":\"");
            AnActEmitName(t, emon.Port.CellsAt(an, at + 12));
            emon.Port.TextAscii(t, "\",\"actions\":");
            emon.Port.TextI32(t, emon.Port.CellsAt(an, at + 31));
        }
        if (emon.Port.CellsAt(an, at + 13) >= 0) {
            emon.Port.TextAscii(t, ",\"target\":");
            Pdfx.PxJsonRun(t, txt, emon.Port.CellsAt(an, at + 13), emon.Port.CellsAt(an, at + 14));
        }
        if (Pdfx.PxDestPresent(an, at + 15) == 1) {
            emon.Port.TextAscii(t, ",\"dest\":");
            Pdfx.PxJsonDest(t, txt, an, at + 15);
        }
        if (emon.Port.CellsAt(an, at + 23) >= 0) {
            emon.Port.TextAscii(t, ",\"contents\":");
            Pdfx.PxJsonRun(t, txt, emon.Port.CellsAt(an, at + 23), emon.Port.CellsAt(an, at + 24));
        }
        if (emon.Port.CellsAt(an, at + 25) >= 0) {
            emon.Port.TextAscii(t, ",\"title\":");
            Pdfx.PxJsonRun(t, txt, emon.Port.CellsAt(an, at + 25), emon.Port.CellsAt(an, at + 26));
        }
        if (emon.Port.CellsAt(an, at + 27) >= 0) {
            emon.Port.TextAscii(t, ",\"name\":");
            Pdfx.PxJsonRun(t, txt, emon.Port.CellsAt(an, at + 27), emon.Port.CellsAt(an, at + 28));
        }
        if (emon.Port.CellsAt(an, at + 29) >= 0) {
            emon.Port.TextAscii(t, ",\"field\":");
            emon.Port.TextI32(t, emon.Port.CellsAt(an, at + 29));
        }
        if (emon.Port.CellsAt(an, at + 32) >= 0) {
            emon.Port.TextAscii(t, ",\"appearance\":");
            Pdfx.PxJsonRun(t, txt, emon.Port.CellsAt(an, at + 32), emon.Port.CellsAt(an, at + 33));
        }
        if (emon.Port.CellsAt(an, at + 34) != 0) {
            emon.Port.TextAscii(t, ",\"apobj\":");
            emon.Port.TextI32(t, emon.Port.CellsAt(an, at + 34));
        }
        if (emon.Port.CellsAt(an, at + 35) >= 0) {
            emon.Port.TextAscii(t, ",\"ca\":");
            emon.Port.TextI32(t, emon.Port.CellsAt(an, at + 35));
        }
        emon.Port.TextAscii(t, ",\"bits\":");
        emon.Port.TextI32(t, emon.Port.CellsAt(an, at + 30));
        if (emon.Port.CellsAt(an, at + 36) >= 0) {
            emon.Port.TextAscii(t, ",\"quads\":[");
            q = 0;
            while (q < emon.Port.CellsAt(an, at + 37)) {
                if (q > 0) {
                    emon.Port.TextAscii(t, ",");
                }
                emon.Port.TextAscii(t, "[");
                k = 0;
                while (k < 8) {
                    if (k > 0) {
                        emon.Port.TextAscii(t, ",");
                    }
                    v = emon.Port.CellsAt(aq, ((emon.Port.CellsAt(an, at + 36) + q) * 8) + k);
                    Pdfx.PxJsonCp(t, v);
                    k += 1;
                }
                emon.Port.TextAscii(t, "]");
                q += 1;
            }
            emon.Port.TextAscii(t, "]");
        }
        emon.Port.TextAscii(t, "}");
        return 0;
    }
