        }
        if (emon.Port.CellsAt(fd, at + 25) >= 0) {
            emon.Port.TextAscii(t, ",\"maxlen\":");
            emon.Port.TextI32(t, emon.Port.CellsAt(fd, at + 25));
        }
        if (emon.Port.CellsAt(fd, at + 26) >= 0) {
            emon.Port.TextAscii(t, ",\"quadding\":");
            emon.Port.TextI32(t, emon.Port.CellsAt(fd, at + 26));
        }
        if (emon.Port.CellsAt(fd, at + 27) >= 0) {
            emon.Port.TextAscii(t, ",\"on\":");
