    internal static int PaDumpSig(System.Text.StringBuilder t, emon.Port.Cells txt, emon.Port.Cells sg, int row) {
        int at = row * SgStride;
        int k = 0;
        emon.Port.TextAscii(t, "{\"field\":");
        emon.Port.TextI32(t, emon.Port.CellsAt(sg, at));
        emon.Port.TextAscii(t, ",\"annot\":");
        emon.Port.TextI32(t, emon.Port.CellsAt(sg, at + 1));
        emon.Port.TextAscii(t, ",\"page\":");
        emon.Port.TextI32(t, emon.Port.CellsAt(sg, at + 2));
        if (emon.Port.CellsAt(sg, at + 2) >= 0) {
            emon.Port.TextAscii(t, ",\"rect\":");
            Pdfx.PxJsonBox(t, sg, at + 3);
        }
        emon.Port.TextAscii(t, ",\"name\":");
        Pdfx.PxJsonRun(t, txt, emon.Port.CellsAt(sg, at + 7), emon.Port.CellsAt(sg, at + 8));
        emon.Port.TextAscii(t, ",\"m\":");
        Pdfx.PxJsonRun(t, txt, emon.Port.CellsAt(sg, at + 9), emon.Port.CellsAt(sg, at + 10));
        if (emon.Port.CellsAt(sg, at + 11) >= 0) {
            emon.Port.TextAscii(t, ",\"date\":[");
            k = 0;
            while (k < 7) {
                if (k > 0) {
                    emon.Port.TextAscii(t, ",");
                }
                emon.Port.TextI32(t, emon.Port.CellsAt(sg, (at + 11) + k));
                k += 1;
            }
            emon.Port.TextAscii(t, "]");
        }
        emon.Port.TextAscii(t, ",\"reason\":");
        Pdfx.PxJsonRun(t, txt, emon.Port.CellsAt(sg, at + 18), emon.Port.CellsAt(sg, at + 19));
        emon.Port.TextAscii(t, ",\"location\":");
        Pdfx.PxJsonRun(t, txt, emon.Port.CellsAt(sg, at + 20), emon.Port.CellsAt(sg, at + 21));
        emon.Port.TextAscii(t, ",\"contact\":");
        Pdfx.PxJsonRun(t, txt, emon.Port.CellsAt(sg, at + 22), emon.Port.CellsAt(sg, at + 23));
        emon.Port.TextAscii(t, ",\"filter\":");
        Pdfx.PxJsonRun(t, txt, emon.Port.CellsAt(sg, at + 24), emon.Port.CellsAt(sg, at + 25));
        emon.Port.TextAscii(t, ",\"subfilter\":");
        Pdfx.PxJsonRun(t, txt, emon.Port.CellsAt(sg, at + 26), emon.Port.CellsAt(sg, at + 27));
        emon.Port.TextAscii(t, ",\"range\":[");
        k = 0;
        while (k < 4) {
            if (k > 0) {
                emon.Port.TextAscii(t, ",");
            }
            emon.Port.TextI32(t, emon.Port.CellsAt(sg, (at + 28) + k));
            k += 1;
        }
        emon.Port.TextAscii(t, "],\"contents\":");
        emon.Port.TextI32(t, emon.Port.CellsAt(sg, at + 32));
        emon.Port.TextAscii(t, ",\"bits\":");
        emon.Port.TextI32(t, emon.Port.CellsAt(sg, at + 33));
        emon.Port.TextAscii(t, "}");
        return 0;
    }
    public static int PaDump(System.Text.StringBuilder t, emon.Port.Cells txt, emon.Port.Cells an, emon.Port.Cells aq, emon.Port.Cells fd, emon.Port.Cells sg) {
        // Annotations, fields and signatures as one canonical JSON object, in row order:
        // `{"annots":[..],"fields":[..],"sigs":[..]}`. Not a public contract (the
        // Model says what it needs of these); it is what the laws and the oracle compare.
        int na = emon.Port.CellsLen(an) / AnStride;
        int nf = emon.Port.CellsLen(fd) / FdStride;
        int ns = emon.Port.CellsLen(sg) / SgStride;
        int i = 0;
        emon.Port.TextAscii(t, "{\"annots\":[");
        while (i < na) {
            if (emon.Port.CellsAt(an, (i * AnStride) + 1) != AnDigsig()) {
                if (i > 0) {
                    emon.Port.TextAscii(t, ",");
                }
                PaDumpAnnot(t, txt, an, aq, i);
            }
            i += 1;
        }
        emon.Port.TextAscii(t, "],\"fields\":[");
        i = 0;
        while (i < nf) {
            if (i > 0) {
                emon.Port.TextAscii(t, ",");
            }
            PaDumpField(t, txt, fd, i);
            i += 1;
        }
        emon.Port.TextAscii(t, "],\"sigs\":[");
        i = 0;
        while (i < ns) {
            if (i > 0) {
                emon.Port.TextAscii(t, ",");
            }
            PaDumpSig(t, txt, sg, i);
            i += 1;
        }
        emon.Port.TextAscii(t, "]}");
        return 0;
    }
